// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        address rewardToken = address(0x1234);
        c.addReward(rewardToken);

        uint40 finish = c.rewardPeriodFinish(rewardToken);

        assertTrue(finish >= uint40(block.timestamp), "rewardPeriodFinish should be non-zero after addReward");
    }
}
